import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"工具接口","link":"/api/SIMD-API/basic_api/tool_interface/tool_interface"},{"text":"系统资源与变量","link":"/api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/system_resources_and_variables"},{"text":"GetSystemCycle(ISASI)","link":"/api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetSystemCycle_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetSystemCycle_ISASI.md","filePath":"api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetSystemCycle_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/tool_interface/system_resources_and_variables/GetSystemCycle_ISASI.md"};function e(t,s,i,o,d,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>GetSystemCycle(ISASI)</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_sys_var_intf.h&quot;</code>。</p><p>获取系统计数器当前的cycle值。通过计算代码段前后cycle值的差值，可得到代码段消耗的系统cycle数，再通过换算即可获得代码段的执行时间。</p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，若换算成时间需要按照1GHz的频率，时间单位为us，换算公式为：time = (cycle数/1000)us。</p></div><div data-filter="A3"><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，若换算成时间需要按照50MHz的频率，时间单位为us，换算公式为：time = (cycle数/50)us。</p></div><div data-filter="910b"><p>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，若换算成时间需要按照50MHz的频率，时间单位为us，换算公式为：time = (cycle数/50)us。</p></div><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">GetSystemCycle</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p>无</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>返回系统计数器当前的cycle值。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>该接口属于PIPE_S流水，若需要测试其他流水的指令时间，需要在调用该接口前通过<a href="../../sync_control/intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier</a>插入对应流水的同步，具体请参考<a href="#example2">调用示例</a>。</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>如下示例通过<code>GetSystemCycle</code>获取系统cycle数，并换算成时间（单位：us）。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;kernel_operator.h&quot;</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">InitTilingParam</span><span class="p">(</span><span class="kt">int32_t</span><span class="o">&amp;</span><span class="w"> </span><span class="n">totalSize</span><span class="p">,</span><span class="w"> </span><span class="kt">int32_t</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loopSize</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">systemCycleBefore</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetSystemCycle</span><span class="p">();</span><span class="w"> </span><span class="c1">// 调用GetBlockNum指令前的cycle数</span>
<span class="w">    </span><span class="n">loopSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">totalSize</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetBlockNum</span><span class="p">();</span>
<span class="w">    </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">systemCycleAfter</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetSystemCycle</span><span class="p">();</span><span class="w"> </span><span class="c1">// 调用GetBlockNum指令后的cycle数</span>
<span class="w">    </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">GetBlockNumCycle</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">systemCycleAfter</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">systemCycleBefore</span><span class="p">;</span><span class="w"> </span><span class="c1">// 执行GetBlockNum指令所用的cycle数</span>
<span class="w">    </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">CycleToTimeBase</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">50</span><span class="p">;</span><span class="w"> </span><span class="c1">// cycle数转换成时间的基准单位</span>
<span class="w">    </span><span class="cm">/* 在Ascend 950PR/Ascend 950DT上为1000</span>
<span class="cm">    在Atlas A3 训练系列产品/Atlas A3 推理系列产品上为50</span>
<span class="cm">    在Atlas A2 训练系列产品/Atlas A2 推理系列产品上为50 */</span>
<span class="w">    </span><span class="kt">int64_t</span><span class="w"> </span><span class="n">GetBlockNumTime</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">GetBlockNumCycle</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">CycleToTimeBase</span><span class="p">;</span><span class="w"> </span><span class="c1">// 执行GetBlockNum指令所用时间，单位为us</span>
<span class="p">};</span>
</code></pre></div></li><li><p><a id="example2"></a>如下示例为获取矢量计算Add指令时间的关键代码片段，在调用<code>GetSystemCycle</code>之前，插入了<code>PIPE_ALL</code>同步，可以保证相关指令执行完后再获取cycle数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>
<span class="kt">int64_t</span><span class="w"> </span><span class="n">systemCycleBefore</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetSystemCycle</span><span class="p">();</span><span class="w"> </span><span class="c1">// 调用Add指令前的cycle数</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">src1Local</span><span class="p">,</span><span class="w"> </span><span class="mi">512</span><span class="p">);</span>
<span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>
<span class="kt">int64_t</span><span class="w"> </span><span class="n">systemCycleAfter</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GetSystemCycle</span><span class="p">();</span><span class="w"> </span><span class="c1">// 调用Add指令后的cycle数</span>
<span class="kt">int64_t</span><span class="w"> </span><span class="n">GetBlockNumCycle</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">systemCycleAfter</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="n">systemCycleBefore</span><span class="p">;</span><span class="w"> </span><span class="c1">// 执行Add指令所用的cycle数</span>
<span class="kt">int64_t</span><span class="w"> </span><span class="n">CycleToTimeBase</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">50</span><span class="p">;</span><span class="w"> </span><span class="c1">// cycle数转换成时间的基准单位</span>
<span class="cm">/* 在Ascend 950PR/Ascend 950DT上为1000</span>
<span class="cm">在Atlas A3 训练系列产品/Atlas A3 推理系列产品上为50</span>
<span class="cm">在Atlas A2 训练系列产品/Atlas A2 推理系列产品上为50 */</span>
<span class="kt">int64_t</span><span class="w"> </span><span class="n">GetBlockNumTime</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">GetBlockNumCycle</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">CycleToTimeBase</span><span class="p">;</span><span class="w"> </span><span class="c1">// 执行Add指令所用时间，单位为us</span>
</code></pre></div></li></ul></article></div>`,1)])])}const _=a(c,[["render",e]]);export{h as __pageData,_ as default};
